import{_ as l,l as i,o as e,c as s,v as r,p as n,x as o,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"时钟恢复与扰码","description":"","frontmatter":{"title":"时钟恢复与扰码","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/clock-recovery-scrambling.md","filePath":"cs/clock-recovery-scrambling.md","lastUpdated":1789023840000}'),E={name:"cs/clock-recovery-scrambling.md"};function h(m,a,_,B,u,C){const t=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="时钟恢复与扰码" tabindex="-1">时钟恢复与扰码 <a class="header-anchor" href="#时钟恢复与扰码" aria-label="Permalink to &quot;时钟恢复与扰码&quot;">​</a></h1><div class="epigraph"><p>串行链路不另送时钟；接收机从跳变里锁相。扰码把用户数据打成伪随机，避免线路码之后仍出现病理游程。</p><footer>—— 据 IEEE 802.3 64B/66B 与扰码条款；Gardner, Phaselock Techniques 整理</footer></div><p><a href="/cs/line-coding">上一课</a>用块编码保证跳变。10G 以后改 64B/66B：同步头只有 2 比特，数据块本身可能仍长 0。缺口是<strong>时钟恢复（CDR）<strong>与</strong>扰码</strong>：锁相从边沿取定时；扰码器用自同步或帧同步多项式打散能量。本课不把铜缆衰减曲线画完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>符号率在吉赫兹，无法再并一根时钟线（相对早期并行总线）。接收 VCO/数字 CDR 跟踪相位；低频抖动用环路带宽折中。若净荷全零，即使 66 比特块有同步头，频谱仍可能有线谱，EMI 与 CDR 都差。扰码（如 \\(x^{58}+x^{39}+1\\) 一类 IEEE 多项式）使输出接近白，且对偶发错误不灾难性扩散——自同步扰码误码增殖有限，帧同步则要边界。</p><p>不要把扰码当成加密：多项式公开，状态可被观察。</p><p><span class="marginnote">64B/66B 见 IEEE 802.3 Clause 49。CDR 是锁相环，不是 MAC 状态机。本课不推 Gardner 鉴定器全文。</span></p><h3 id="扰码不是加密" tabindex="-1">扰码不是加密 <a class="header-anchor" href="#扰码不是加密" aria-label="Permalink to &quot;扰码不是加密&quot;">​</a></h3><p>多项式公开，状态可被观察。CDR 跟的是边沿，不是 MAC 状态机。丢锁表现为口 down，排障应先看 PHY，再看 STP。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>PCS：64 比特 → 加 2 比特同步头 → 扰码 → 串行。接收：CDR 抽样 → 解扰 → 找同步头锁定块边界。丢失锁定则链路 fault，上层看到 carrier down，不是 TCP 超时本身。</p>',11)),(e(),n(p,null,{default:o(()=>[d(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20BLK%5B%2264B%20%2B%20%E5%90%8C%E6%AD%A5%E5%A4%B4%22%5D%20--%3E%20SCR%5B%22%E6%89%B0%E7%A0%81%22%5D%0A%20%20SCR%20--%3E%20SER%5B%22%E4%B8%B2%E8%A1%8C%22%5D%0A%20%20SER%20--%3E%20CDR%5B%22%E9%94%81%E7%9B%B8%E6%8A%BD%E6%A0%B7%22%5D%0A%20%20CDR%20--%3E%20DSCR%5B%22%E8%A7%A3%E6%89%B0%E4%B8%8E%E5%9D%97%E9%94%81%E5%AE%9A%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>容量与调制假定接收机知道抽样时刻。本课把「知道」做成环路：跟踪频差与慢漂移。交换机端口 up/down 往往先死在 CDR/块锁，而不是 STP。主干<a href="/cs/frame-mac">帧</a>的前导码在铜缆千兆仍帮对齐；高速串行则把对齐下放到 PCS 同步头。</p><p>扰码与 8B/10B 分工：后者保证局部游程；前者在低开销块码上保证统计跳变。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 SerDes 的 FFE/DFE 抽头训练全集（那是铜缆均衡）。介质衰减与光纤是下一课。后课默认：无独立时钟线；扰码公开且为频谱服务。</p><p>病理图案仍可能通过短周期测试向量构造，标准用禁则与测试模式排除，不在课上穷举。</p><p>上一课留下的缺口在本课收口；「时钟恢复与扰码」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/copper-fiber-media">铜缆、光纤与衰减</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CDR 从数据边沿恢复波特时钟。</li><li>扰码打散能量，不是保密。</li><li>64B/66B 用低开销同步头加扰码替代重块码。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：IEEE 802.3 Clause 49；Gardner。</li></ul>',10))])}const A=l(E,[["render",h]]);export{D as __pageData,A as default};
